"""Tests for the standalone bfs_shortest_path function."""

from bfs_shortest_path import bfs_shortest_path


def test_shortest_path_found():
    g = {0: [1, 3], 1: [0, 2], 2: [1, 5], 3: [0, 4], 4: [3, 5, 6], 5: [2, 4], 6: [4]}
    assert bfs_shortest_path(g, 0, 6) == [0, 3, 4, 6]


def test_start_equals_end():
    g = {0: [1], 1: [0]}
    assert bfs_shortest_path(g, 0, 0) == [0]


def test_no_path():
    g = {0: [1], 2: [3]}
    assert bfs_shortest_path(g, 0, 3) is None


def test_missing_start():
    g = {0: [1]}
    assert bfs_shortest_path(g, 99, 1) is None


def test_missing_end():
    g = {0: [1]}
    assert bfs_shortest_path(g, 0, 99) is None


def test_linear_chain():
    g = {0: [1], 1: [0, 2], 2: [1, 3], 3: [2]}
    path = bfs_shortest_path(g, 0, 3)
    assert path == [0, 1, 2, 3]


def test_picks_shortest_not_first_found():
    # Direct edge A-D is shorter than A-B-C-D
    g = {"A": ["B", "D"], "B": ["A", "C"], "C": ["B", "D"], "D": ["A", "C"]}
    assert bfs_shortest_path(g, "A", "D") == ["A", "D"]


def test_cycle_no_infinite_loop():
    g = {0: [1], 1: [0, 2], 2: [1]}
    assert bfs_shortest_path(g, 0, 2) == [0, 1, 2]


def test_empty_graph():
    assert bfs_shortest_path({}, 0, 1) is None
